    fn rotation_tolerates_corrupted_stamp() {
        let dir = tempfile::tempdir().unwrap();
        let stamp = dir.path().join(".hooks-rotation-stamp");
        std::fs::write(&stamp, "garbage-not-a-number").unwrap();

