   288// ---------------------------------------------------------------------------
   289// Helpers used by the three follow-up tests below
   290// ---------------------------------------------------------------------------
   291
   292/// Read one HTTP/1.1 request from `stream` (headers + Content-Length body) and
   293/// return the full bytes received. Returns the raw bytes so callers can split
   294/// header / body themselves.
   295async fn read_full_http_request(stream: &mut tokio::net::TcpStream) -> Vec<u8> {
   296    let mut buf = Vec::with_capacity(64 * 1024);
   297    let mut tmp = [0u8; 8192];
   298
   299    // Read until end of headers
   300    let header_end;
   301    loop {
   302        let n = stream.read(&mut tmp).await.expect("read upstream req");
   303        if n == 0 {
   304            return buf;
   305        }
   306        buf.extend_from_slice(&tmp[..n]);
   307        if let Some(idx) = find_subseq(&buf, b"\r\n\r\n") {
   308            header_end = idx + 4;
   309            break;
   310        }
   311    }
   312
   313    // Parse Content-Length
   314    let header_str = String::from_utf8_lossy(&buf[..header_end]).to_lowercase();
   315    let cl: usize = header_str
   316        .lines()
   317        .find_map(|l| l.strip_prefix("content-length:"))
   318        .and_then(|v| v.trim().parse().ok())
   319        .unwrap_or(0);
   320
   321    // Read the rest of the body
   322    while buf.len() < header_end + cl {
   323        let n = stream.read(&mut tmp).await.expect("read upstream body");
   324        if n == 0 {
   325            break;
   326        }
   327        buf.extend_from_slice(&tmp[..n]);
   328    }
   329    buf
   330}
   331
   332fn find_subseq(haystack: &[u8], needle: &[u8]) -> Option<usize> {
   333    haystack.windows(needle.len()).position(|w| w == needle)
   334}
   335
   336/// Write a complete HTTP/1.1 200 response with a JSON body containing a `usage`
   337/// block so the proxy persists a ledger row.
   338async fn write_usage_response(stream: &mut tokio::net::TcpStream, input_tokens: u64) {
   339    let body = json!({
   340        "id": "msg_test",
   341        "type": "message",
   342        "role": "assistant",
   343        "content": [{"type": "text", "text": "ok"}],
   344        "model": "claude-test",
   345        "stop_reason": "end_turn",
   346        "usage": {
   347            "input_tokens": input_tokens,
   348            "output_tokens": 1,
   349            "cache_read_input_tokens": 0,
   350            "cache_creation_input_tokens": 0
   351        }
   352    })
   353    .to_string();
   354    let resp = format!(
   355        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
   356        body.len(),
   357        body
   358    );
   359    let _ = stream.write_all(resp.as_bytes()).await;
