   363/// Spawn the proxy binary with the given env, optional cwd, and wait briefly
   364/// for it to be listening. Caller must kill/wait on the returned Child.
   365///
   366/// Uses the pre-built binary (`CARGO_BIN_EXE_ostk-cache`) so we can set an
   367/// arbitrary cwd without `cargo run` failing to locate the workspace Cargo.toml.
   368fn spawn_proxy(
   369    proxy_port: u16,
   370    upstream_url: &str,
   371    cwd: Option<&std::path::Path>,
   372) -> std::process::Child {
   373    let bin = env!("CARGO_BIN_EXE_ostk-cache");
   374    let mut cmd = Command::new(bin);
   375    cmd.env("PROXY_PORT", proxy_port.to_string())
   376        .env("ANTHROPIC_BASE_URL", upstream_url);
   377    if let Some(p) = cwd {
   378        cmd.current_dir(p);
   379    }
   380    cmd.spawn().expect("Failed to start proxy")
   381}
