   383async fn wait_for_proxy(port: u16, timeout_ms: u64) {
   384    let deadline =
   385        std::time::Instant::now() + std::time::Duration::from_millis(timeout_ms);
   386    loop {
   387        if tokio::net::TcpStream::connect(("127.0.0.1", port)).await.is_ok() {
   388            return;
   389        }
   390        if std::time::Instant::now() >= deadline {
   391            panic!("proxy did not come up on port {} within {}ms", port, timeout_ms);
   392        }
   393        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
   394    }
   395}
