   514    let client = reqwest::Client::new();
   515    let req_task = tokio::spawn(async move {
   516        let resp = client
   517            .post(&proxy_url)
   518            .header("x-api-key", "k")
   519            .header("anthropic-session-id", "ct-test")
   520            .header("content-type", "application/json; charset=utf-8")
   521            .body(req_body)
   522            .send()
   523            .await;
   524        // Drain to completion so the proxy finishes its work cleanly.
   525        if let Ok(r) = resp {
   526            let status = r.status();
   527            let _ = r.bytes().await;
   528            status
   529        } else {
   530            reqwest::StatusCode::INTERNAL_SERVER_ERROR
   531        }
   532    });
   533
   534    let (mut stream, _) = mock_upstream.accept().await.unwrap();
   535    let req_bytes = read_full_http_request(&mut stream).await;
   536    write_usage_response(&mut stream, 1).await;
   537
   538    let status = req_task.await.unwrap();
   539    let _ = proxy.kill();
   540    let _ = proxy.wait();
   541
   542    assert_eq!(status.as_u16(), 200, "proxy must accept charset-qualified content-type and return 200");
   543
   544    let received = String::from_utf8_lossy(&req_bytes);
   545    let lower = received.to_lowercase();
   546
   547    let canonical = lower.matches("content-type: application/json\r\n").count();
   548    let with_charset = lower.matches("content-type: application/json; charset=utf-8").count();
   549    assert_eq!(
   550        canonical, 1,
   551        "upstream must see canonical `content-type: application/json` exactly once, got {} (raw: {:?})",
   552        canonical, received
   553    );
   554    assert_eq!(
   555        with_charset, 0,
   556        "proxy must not propagate the caller's `charset=utf-8` suffix upstream, got {}",
   557        with_charset
   558    );
   559
   560    // Body before the headers/body split must be parseable JSON — confirms the
   561    // proxy did not mangle the payload while normalizing the content-type.
   562    let body_idx = find_subseq(&req_bytes, b"\r\n\r\n").expect("upstream req has body separator") + 4;
   563    let body = &req_bytes[body_idx..];
   564    let parsed: serde_json::Value = serde_json::from_slice(body)
   565        .unwrap_or_else(|e| panic!("upstream body must be valid JSON, got error {}: {:?}", e, String::from_utf8_lossy(body)));
   566    assert_eq!(parsed["messages"][0]["role"], "user");
   567}
