   572
   573#[tokio::test]
   574async fn ledger_jsonl_survives_proxy_sigkill_and_remains_appendable() {
   575    // Sequence:
   576    //   1. Spawn proxy in a tempdir cwd, fire one full request, wait for the
   577    //      ledger row to land on disk.
   578    //   2. SIGKILL the proxy (simulates abrupt crash, no graceful shutdown).
   579    //   3. Re-spawn proxy in the same cwd, fire another full request.
   580    //   4. Verify ledger.jsonl now has 2 well-formed JSON rows (the first row
   581    //      survived the kill, the second appended cleanly).
   582    let mock_upstream = TcpListener::bind("127.0.0.1:0").await.unwrap();
   583    let upstream_addr = mock_upstream.local_addr().unwrap();
   584    let upstream_url = format!("http://127.0.0.1:{}", upstream_addr.port());
   585
   586    let tmp = tempfile::tempdir().expect("tempdir");
   587    let ledger_path = tmp.path().join(".ostk/memory/ledger.jsonl");
   588
   589    // ---- Phase 1: first proxy, one completed request, wait for row ----
   590    let proxy_port_a = 8095;
   591    let mut proxy_a = spawn_proxy(proxy_port_a, &upstream_url, Some(tmp.path()));
   592    wait_for_proxy(proxy_port_a, 5000).await;
   593
   594    let url_a = format!("http://127.0.0.1:{}/v1/messages", proxy_port_a);
   595    let req_task = tokio::spawn(async move {
   596        let client = reqwest::Client::new();
   597        let resp = client
   598            .post(&url_a)
   599            .header("x-api-key", "k")
   600            .header("anthropic-session-id", "crash-sess-1")
   601            .json(&json!({"system": "S", "messages": [{"role": "user", "content": "hi"}]}))
   602            .send()
   603            .await;
   604        if let Ok(r) = resp {
   605            let _ = r.bytes().await;
   606        }
   607    });
   608
   609    let (mut up, _) = mock_upstream.accept().await.unwrap();
   610    let _ = read_full_http_request(&mut up).await;
   611    write_usage_response(&mut up, 50).await;
   612    let _ = req_task.await;
   613
   614    // Wait for the ledger row to actually land before we kill -9.
   615    let mut tries = 0;
   616    while tries < 100 {
   617        if let Ok(s) = std::fs::read_to_string(&ledger_path)
   618            && s.lines().filter(|l| !l.trim().is_empty()).count() >= 1
   619        {
   620            break;
   621        }
   622        tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;
   623        tries += 1;
   624    }
   625    let pre_crash = std::fs::read_to_string(&ledger_path)
   626        .expect("ledger.jsonl must exist before crash");
   627    assert!(
   628        pre_crash.lines().filter(|l| !l.trim().is_empty()).count() >= 1,
   629        "expected at least one ledger row before SIGKILL, got: {:?}", pre_crash
   630    );
   631
   632    // ---- Phase 2: SIGKILL (force kill — no chance for graceful shutdown) ----
   633    // The cargo wrapper PID is not the binary PID; killing it leaves the
   634    // child running. Send SIGKILL to the actual ostk-cache binary using pkill
   635    // scoped to our PROXY_PORT env via the cmdline arg PROXY_PORT=8095.
   636    // std::process::Child::kill on macOS sends SIGKILL, which is propagated to
   637    // the cargo subprocess. To be sure the proxy binary itself dies, we also
   638    // pkill any matching binary with our specific port env in its environment.
   639    let _ = proxy_a.kill(); // SIGKILL on Unix
   640    let _ = proxy_a.wait();
   641    // Best-effort: kill any lingering child that didn't go down with cargo.
   642    let _ = std::process::Command::new("pkill")
   643        .arg("-9")
   644        .arg("-f")
   645        .arg(format!("PROXY_PORT={}", proxy_port_a))
   646        .output();
   647    // Wait for the port to actually free.
   648    for _ in 0..50 {
   649        if tokio::net::TcpStream::connect(("127.0.0.1", proxy_port_a)).await.is_err() {
   650            break;
   651        }
   652        tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
   653    }
   654
   655    // The pre-crash ledger contents must still be on disk and parseable.
   656    let after_crash = std::fs::read_to_string(&ledger_path)
   657        .expect("ledger.jsonl must still exist after SIGKILL");
   658    let rows_after_crash: Vec<serde_json::Value> = after_crash
   659        .lines()
   660        .filter(|l| !l.trim().is_empty())
   661        .map(|l| serde_json::from_str(l)
   662             .unwrap_or_else(|e| panic!("ledger row corrupted after crash: {} (line: {:?})", e, l)))
   663        .collect();
   664    assert!(
   665        !rows_after_crash.is_empty(),
   666        "ledger rows written before crash must survive SIGKILL"
   667    );
   668    let pre_count = rows_after_crash.len();
   669
   670    // ---- Phase 3: restart proxy in the same cwd; fire another request ----
   671    let proxy_port_b = 8096;
   672    let mut proxy_b = spawn_proxy(proxy_port_b, &upstream_url, Some(tmp.path()));
   673    wait_for_proxy(proxy_port_b, 10_000).await;
   674
   675    let url_b = format!("http://127.0.0.1:{}/v1/messages", proxy_port_b);
   676    let req_task2 = tokio::spawn(async move {
   677        let client = reqwest::Client::new();
   678        let resp = client
   679            .post(&url_b)
   680            .header("x-api-key", "k")
   681            .header("anthropic-session-id", "crash-sess-2")
   682            .json(&json!({"system": "S", "messages": [{"role": "user", "content": "hi"}]}))
   683            .send()
   684            .await;
   685        if let Ok(r) = resp {
   686            let _ = r.bytes().await;
   687        }
   688    });
   689
   690    let (mut up2, _) = mock_upstream.accept().await.unwrap();
   691    let _ = read_full_http_request(&mut up2).await;
   692    write_usage_response(&mut up2, 75).await;
   693    let _ = req_task2.await;
   694
   695    // Wait for the new row to land.
   696    let mut tries = 0;
   697    while tries < 100 {
   698        if let Ok(s) = std::fs::read_to_string(&ledger_path)
   699            && s.lines().filter(|l| !l.trim().is_empty()).count() > pre_count
   700        {
   701            break;
   702        }
   703        tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;
   704        tries += 1;
   705    }
   706
   707    let _ = proxy_b.kill();
   708    let _ = proxy_b.wait();
   709
   710    let final_content = std::fs::read_to_string(&ledger_path)
   711        .expect("ledger.jsonl must exist after restart and second request");
   712    let final_rows: Vec<serde_json::Value> = final_content
   713        .lines()
   714        .filter(|l| !l.trim().is_empty())
   715        .map(|l| serde_json::from_str(l)
   716             .unwrap_or_else(|e| panic!("ledger row not valid JSON after restart: {} (line: {:?})", e, l)))
   717        .collect();
   718    assert!(
   719        final_rows.len() > pre_count,
   720        "expected new ledger row appended after restart (had {}, now {}): {}",
   721        pre_count, final_rows.len(), final_content
   722    );
   723    // Confirm pre-crash rows are still byte-identical at the front of the file
   724    // — no truncation, no rewrite during restart.
   725    assert!(
   726        final_content.starts_with(&after_crash),
   727        "post-restart ledger must start with pre-crash bytes (append-only invariant)"
   728    );
   729
   730    // Confirm the new row carries the second session id.
   731    let last = final_rows.last().expect("at least one row");
   732    assert_eq!(
   733        last["session"].as_str(),
   734        Some("crash-sess-2"),
   735        "post-restart row should carry the second session id"
   736    );
   737}
