   742
   743/// Helper for /hook/event tests: spawn proxy in tempdir, return (child, port,
   744/// tempdir handle). Caller drives requests against `http://127.0.0.1:<port>/hook/event`.
   745async fn spawn_hook_proxy(port: u16) -> (std::process::Child, tempfile::TempDir) {
   746    let tmp = tempfile::tempdir().expect("tempdir");
   747    // No upstream is needed for /hook/event — pass a bogus URL just so the env
   748    // var is set (the proxy never contacts upstream for hook events).
   749    let mut child = spawn_proxy(port, "http://127.0.0.1:1", Some(tmp.path()));
   750    // Wait for the port to come up; if the binary fails to start, surface that.
   751    let deadline = std::time::Instant::now() + std::time::Duration::from_millis(5000);
   752    loop {
   753        if tokio::net::TcpStream::connect(("127.0.0.1", port)).await.is_ok() {
   754            break;
   755        }
   756        if std::time::Instant::now() >= deadline {
   757            let _ = child.kill();
   758            panic!("hook proxy did not come up on port {} within 5000ms", port);
   759        }
   760        tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;
   761    }
   762    (child, tmp)
   763}
