   777#[tokio::test]
   778async fn hook_endpoint_accepts_all_five_event_types_and_writes_correct_rows() {
   779    // Each of the 5 valid Claude Code event types should:
   780    //   * return 200 on POST /hook/event
   781    //   * append exactly one row to .l1.5/hooks.jsonl carrying the matching
   782    //     event_type, the workspace_id and session_id we sent, and our payload.
   783    let (mut proxy, tmp) = spawn_hook_proxy(8097).await;
   784    let url = "http://127.0.0.1:8097/hook/event";
   785    let client = reqwest::Client::new();
   786
   787    // Order matters only for the row sequence we assert at the end.
   788    let events = [
   789        ("SessionStart", json!({"reason": "boot"})),
   790        ("UserPromptSubmit", json!({"prompt": "hi"})),
   791        ("PreToolUse", json!({"tool": "echo"})),
   792        ("PostToolUse", json!({"tool": "echo", "ok": true})),
   793        ("Stop", json!({"reason": "user"})),
   794    ];
   795
   796    for (idx, (kind, payload)) in events.iter().enumerate() {
   797        let body = json!({
   798            "type": kind,
   799            "workspace_id": "ws-hook-test",
   800            "session_id": format!("sess-hook-{}", idx),
   801            "payload": payload,
   802        });
   803        let resp = client.post(url).json(&body).send().await
   804            .unwrap_or_else(|e| panic!("POST /hook/event failed for {}: {}", kind, e));
   805        assert_eq!(
   806            resp.status().as_u16(),
   807            200,
   808            "expected 200 for valid event {}, got {}",
   809            kind, resp.status()
   810        );
   811        let body: serde_json::Value = resp.json().await.expect("response is JSON");
   812        assert_eq!(body["ok"], json!(true), "valid event response should include {{\"ok\":true}}");
   813    }
   814
   815    // Allow filesystem flush before reading.
   816    tokio::time::sleep(tokio::time::Duration::from_millis(50)).await;
   817
   818    let _ = proxy.kill();
   819    let _ = proxy.wait();
   820
   821    let rows = read_hooks_jsonl(tmp.path());
   822    assert_eq!(
   823        rows.len(),
   824        events.len(),
   825        "expected one hooks.jsonl row per event, got {} rows for {} events",
   826        rows.len(), events.len()
   827    );
   828
   829    for (idx, (kind, payload)) in events.iter().enumerate() {
   830        let row = &rows[idx];
   831        assert_eq!(row["event_type"].as_str(), Some(*kind),
   832            "row {} has wrong event_type: {:?}", idx, row);
   833        assert_eq!(row["workspace_id"].as_str(), Some("ws-hook-test"),
   834            "row {} has wrong workspace_id: {:?}", idx, row);
   835        assert_eq!(
   836            row["session_id"].as_str(),
   837            Some(format!("sess-hook-{}", idx).as_str()),
   838            "row {} has wrong session_id: {:?}", idx, row
   839        );
   840        assert_eq!(&row["payload"], payload,
   841            "row {} payload mismatch: {:?} vs {:?}", idx, row["payload"], payload);
   842        assert!(row["timestamp"].is_string() || row["timestamp"].is_number(),
   843            "row {} timestamp should be present: {:?}", idx, row);
   844    }
   845}
